package android.os; import java.util.*; public class Binder implements IBinder {public boolean alive=true; public final List<DeathRecipient> deaths=new ArrayList<>(); public boolean isBinderAlive(){return alive;} public void linkToDeath(DeathRecipient d,int f)throws RemoteException{if(!alive)throw new RemoteException(); deaths.add(d);} public boolean unlinkToDeath(DeathRecipient d,int f){return deaths.remove(d);} public void die(){alive=false; for(DeathRecipient d:new ArrayList<>(deaths))d.binderDied();} public static int getCallingUid(){return 2000;} public static long clearCallingIdentity(){return 0;} public static void restoreCallingIdentity(long n){} }
